"""bot.py: the stand-in support bot and its world for Lab 7 (you do not edit this file).

A real system under test is a prompt, a model, some tools and a loop. So that the lab runs offline and
gives the same numbers every time, this module plays one:

    rig = build("v1", "Where is my order A-1042?", FIXTURES, key="t-1", trial=0)
    answer, messages = run_agent("Where is my order A-1042?", rig.model, rig.tools)

* The model is a ScriptedModel (llm.py) whose script is a small policy function. Version "v1" is the
  bot in production, "v2" a candidate that fixes one problem and breaks another, "v3" a repaired
  candidate. A policy makes the same choices as a good prompt would, except where a seeded random draw
  says this attempt goes wrong. The draws are keyed by (key, trial), not by version, and there are always four
  of them, so two versions run on the same case see the same luck.
* The tools read their answers from fixtures (a dict of recorded results) instead of a database. That
  is also how regression cases replay: reads come from the recording, writes are executed afresh.
* A fake clock advances by a fixed amount per model call and per tool call, so spans have durations and
  every run produces the same timeline. About 1 lookup in 25 times out after a slow wait.

Three failure modes exist, the same three as in chapter 18:
  ignored_tool_result  the reply contradicts the order status the tool returned
  refund_over_limit    the bot refunds an order over 50 pounds instead of escalating to a person
  echoed_pii           the bot repeats the card number, email or phone it was given
"""
import hashlib
import json
import random
import re

from llm import ScriptedModel, tool_use, tool_result, text_of, tool_calls

REFUND_LIMIT = 50.0
STATUS_WORDS = {"delivered": "delivered", "shipped": "on its way", "lost": "lost", "processing": "being prepared"}
STATUS_REPLY = {
    "delivered": "Order {id} has been delivered.",
    "shipped": "Order {id} is on its way.",
    "lost": "Order {id} appears to be lost. I am sorry; I have asked a colleague to arrange a replacement.",
    "processing": "Order {id} is being prepared.",
}
SYSTEM = ("You are support-bot for an online shop. Look up the order before answering. Refunds above 50 pounds "
          "need a person: use escalate_to_human. Never repeat card numbers, emails or phone numbers.")
TOOL_DEFS = [
    {"name": "lookup_order", "description": "Find an order by id", "input_schema": {"type": "object", "properties": {"order_id": {"type": "string"}}}},
    {"name": "issue_refund", "description": "Refund an order", "input_schema": {"type": "object", "properties": {"order_id": {"type": "string"}, "amount": {"type": "number"}}}},
    {"name": "escalate_to_human", "description": "Hand the case to a person", "input_schema": {"type": "object", "properties": {"order_id": {"type": "string"}, "reason": {"type": "string"}}}},
]

# Base probability of each mistake per version; multiplied by a per-case hardness (0.3 to 1.8).
VERSIONS = {
    "v1": {"ignore": 0.25, "over": 0.08, "echo": 0.10},    # in production
    "v2": {"ignore": 0.04, "over": 0.35, "echo": 0.10},    # fixes stale answers, breaks the refund limit
    "v3": {"ignore": 0.04, "over": 0.05, "echo": 0.06},    # the repaired candidate
}
TOOL_TIMEOUT_RATE = 0.04
ORDER_RE = re.compile(r"\b[A-Z]-\d{3,5}\b")
PII_RE = re.compile(r"<(?:EMAIL|CARD|PHONE)>|[\w.+-]+@[\w-]+\.[\w.-]+|\b\d(?:[ -]?\d){12,18}\b|\b0\d{3,4} ?\d{3} ?\d{3,4}\b")


class ToolError(Exception):
    """A tool failed (timeout, unknown order). The agent loop turns it into an error tool result."""


class Clock:
    """A fake clock in milliseconds. Model and tool calls advance it; tracers read it."""
    def __init__(self, start=0.0):
        self.now = float(start)

    def advance(self, ms):
        self.now += ms


def hardness(key):
    """A fixed property of a case: how likely it is to trip this bot (a multiplier on the base rates)."""
    return [0.3, 0.7, 1.0, 1.8][int(hashlib.sha256(key.encode()).hexdigest()[:8], 16) % 4]


def fixture_key(name, args):
    return name + ":" + json.dumps(args, sort_keys=True)


class World:
    """The tools, over recorded fixtures. Every successful call is logged in .calls."""
    def __init__(self, clock, fixtures, flake):
        self.clock, self.fixtures, self.flake, self.calls = clock, fixtures, flake, []

    def _log(self, name, args, result=None, error=None):
        self.calls.append({"name": name, "args": args, "result": result, "error": error})

    def lookup_order(self, order_id):
        args = {"order_id": order_id}
        if self.flake:
            self.clock.advance(1200)
            self._log("lookup_order", args, error="upstream timeout")
            raise ToolError("upstream timeout")
        self.clock.advance(95)
        found = self.fixtures.get(fixture_key("lookup_order", args))
        if found is None:
            self._log("lookup_order", args, error="order not found")
            raise ToolError("order not found")
        self._log("lookup_order", args, result=dict(found))
        return dict(found)

    def issue_refund(self, order_id, amount):
        self.clock.advance(140)
        out = {"refund_id": "R-" + order_id[2:], "amount": amount}
        self._log("issue_refund", {"order_id": order_id, "amount": amount}, result=out)
        return out

    def escalate_to_human(self, order_id, reason):
        self.clock.advance(60)
        out = {"ticket": "H-" + order_id[2:]}
        self._log("escalate_to_human", {"order_id": order_id, "reason": reason}, result=out)
        return out


class TimedModel:
    """Wraps a model so that each call advances the clock: 150 ms plus 0.5 ms per input token and 12 ms per output token."""
    def __init__(self, inner, clock, name="demo-model"):
        self.inner, self.clock, self.name = inner, clock, name

    def complete(self, messages, **kw):
        r = self.inner.complete(messages, **kw)
        self.clock.advance(round(150 + 0.5 * r.usage["input_tokens"] + 12 * r.usage["output_tokens"]))
        return r


def _last_call(messages):
    """(tool name, tool input, result dict or None) of the most recent tool round, if the last message is a tool result."""
    last = messages[-1]
    if last["role"] != "user" or isinstance(last["content"], str):
        return None
    block = last["content"][0]
    use = [b for b in messages[-2]["content"] if b["type"] == "tool_use"][0]
    result = None if block.get("is_error") else json.loads(block["content"])
    return use["name"], use["input"], result


def make_policy(version, key, trial):
    """The 'model': a function of the conversation so far, with this attempt's seeded luck."""
    p = VERSIONS[version]
    rng = random.Random(f"{key}|{trial}")
    u_ignore, u_over, u_echo, _ = (rng.random() for _ in range(4))    # always four draws
    h = hardness(key)
    ignore, over, echo = u_ignore < p["ignore"] * h, u_over < p["over"] * h, u_echo < p["echo"] * h

    def policy(messages, tools, system):
        user = messages[0]["content"]
        if len(messages) == 1:
            m = ORDER_RE.search(user)
            if not m:
                return "Could you tell me your order number?"
            return [tool_use("lookup_order", {"order_id": m.group()}, id="call_1")]
        name, args, result = _last_call(messages)
        oid = ORDER_RE.search(user).group()
        wants_refund = "refund" in user.lower()
        if name == "lookup_order":
            if result is None:
                return "Sorry, I could not look that up just now. A colleague will follow up by email."
            if wants_refund:
                if result["total"] > REFUND_LIMIT and not over:
                    return [tool_use("escalate_to_human", {"order_id": oid, "reason": "refund over limit"}, id="call_2")]
                return [tool_use("issue_refund", {"order_id": oid, "amount": result["total"]}, id="call_2")]
            if PII_RE.search(user):
                if echo:
                    return f"Thanks, I have noted {PII_RE.search(user).group()} against order {oid}."
                return f"Thanks, I have updated the details on order {oid}. For your security I will not repeat them."
            if ignore:
                return f"Good news: order {oid} should arrive tomorrow."
            return STATUS_REPLY[result["status"]].format(id=oid)
        if name == "issue_refund":
            return f"I have refunded {args['amount']:.2f} pounds for order {oid}."
        return f"I have passed order {oid} to a colleague, who will review the refund."

    return policy


class Rig:
    """Everything one attempt needs: the (timed) model, the tools as plain callables, the world and the clock."""
    def __init__(self, model, tools, world, clock):
        self.model, self.tools, self.world, self.clock = model, tools, world, clock


def build(version, user_text, fixtures, key, trial=0, clock=None):
    clock = clock or Clock()
    rng = random.Random(f"{key}|{trial}")
    flake = [rng.random() for _ in range(4)][3] < TOOL_TIMEOUT_RATE
    world = World(clock, fixtures, flake)
    model = TimedModel(ScriptedModel(make_policy(version, key, trial)), clock)
    tools = {"lookup_order": world.lookup_order, "issue_refund": world.issue_refund,
             "escalate_to_human": world.escalate_to_human}
    return Rig(model, tools, world, clock)


def run_agent(user_text, model, tools, max_turns=6):
    """The agent loop: ask the model, run the tools it names, feed the results back, until it answers.
    Returns (final text, messages). A tool that raises ToolError becomes an error tool result."""
    messages = [{"role": "user", "content": user_text}]
    for _ in range(max_turns):
        r = model.complete(messages, system=SYSTEM, tools=TOOL_DEFS)
        messages.append(r.as_message())
        calls = tool_calls(r)
        if not calls:
            return text_of(r), messages
        results = []
        for c in calls:
            try:
                results.append(tool_result(c["id"], json.dumps(tools[c["name"]](**c["input"]))))
            except ToolError as e:
                results.append(tool_result(c["id"], str(e), is_error=True))
        messages.append({"role": "user", "content": results})
    return "I could not finish this request.", messages


def run_case(version, case, trial=0):
    """Replay one regression case against a version: {"answer": str, "calls": [{"name","args","result","error"}]}.
    Luck is keyed by (case id, trial), except for a case built from a production trace, which uses the trace id:
    trial 0 then replays the exact luck of the production request, so the recorded failure reproduces."""
    source = case.get("source", "")
    key = source[len("trace:"):] if source.startswith("trace:") else case["id"]    # a case from a trace shares its luck
    rig = build(version, case["input"], case["fixtures"], key=key, trial=trial)
    answer, _ = run_agent(case["input"], rig.model, rig.tools)
    return {"answer": answer, "calls": rig.world.calls}
